#include "stdlib/lapack/base/dla_porpvgrw.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define REPEATS 2
#define ITERATIONS 1000

/**
* Benchmarks the growth routine on diagonal positive-definite matrices.
*
* @param N       matrix order
* @return        elapsed seconds
*/
static double benchmark( const LAPACK_INT N ) {
	double *A;
	double *AF;
	double *WORK;
	double result;
	LAPACK_INT i;
	clock_t time;

	A = (double *)calloc( N*N, sizeof( double ) );
	AF = (double *)calloc( N*N, sizeof( double ) );
	WORK = (double *)malloc( 2*N*sizeof( double ) );
	if ( A == NULL || AF == NULL || WORK == NULL ) {
		free( A ); free( AF ); free( WORK );
		exit( 1 );
	}
	for ( i = 0; i < N; i++ ) {
		A[ i*(N+1) ] = 0.25;
		AF[ i*(N+1) ] = 0.5;
	}
	time = clock();
	for ( i = 0; i < ITERATIONS; i++ ) {
		result = API_SUFFIX(c_dla_porpvgrw)( LAPACK_ROW_MAJOR, LAPACK_UPPER_TRIANGLE, N, A, N, AF, N, WORK );
		if ( result != 0.5 ) {
			free( A ); free( AF ); free( WORK );
			exit( 1 );
		}
	}
	time = clock()-time;
	free( A ); free( AF ); free( WORK );
	return (double)time/CLOCKS_PER_SEC;
}

int main( void ) {
	const LAPACK_INT sizes[] = { 1, 16, 64 };
	double elapsed;
	int count;
	int i;
	int j;

	printf( "TAP version 13\n" );
	count = 0;
	for ( i = 0; i < 3; i++ ) {
		for ( j = 0; j < REPEATS; j++ ) {
			elapsed = benchmark( sizes[i] );
			count += 1;
			printf( "# c::dla-porpvgrw:N=%" LAPACK_IFMT "\n", sizes[i] );
			printf( "  ---\n  iterations: %d\n  elapsed: %.9f\n  ...\n", ITERATIONS, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	printf( "1..%d\n# pass %d\n# ok\n", count, count );
	return 0;
}
